const GLOSSARY = [
 ['At-least-once delivery','A message may be delivered again; consumers must tolerate duplicates.'],['Backpressure','A mechanism that slows producers when consumers or dependencies are saturated.'],['Bounded context','A boundary inside which a domain model and language are consistent.'],['Circuit breaker','A state machine that temporarily blocks calls after failures cross a threshold.'],['Consumer group','Kafka consumers sharing partitions so one member processes each partition at a time.'],['Error budget','The allowed unreliability implied by an SLO.'],['Fencing token','A monotonically increasing token used by a resource to reject stale lease holders.'],['Idempotency','The property that repeated execution has the same intended effect as one execution.'],['Outbox','Events stored atomically with business state, then relayed asynchronously.'],['Partial failure','Some components or links fail while the rest of the distributed system continues.'],['Quorum','The number of replicas required to accept a read or write decision.'],['Saga','A sequence of local transactions with explicit compensating actions.'],['SLI','A measured indicator of service behavior, such as successful request ratio.'],['SLO','A target range for an SLI over a time window.'],['Tail latency','The slow end of a latency distribution, commonly p95 or p99.']
];

